"""Configuration loading: config/base.json overlaid by config/<env>.json; ${VAR} references are resolved from the environment."""
import os
import re

import json


def _parse(path):
    with open(path, encoding="utf-8") as fh:
        return json.load(fh)


class ConfigError(Exception):
    """The configuration cannot be used."""


def _expand(value):
    if not isinstance(value, str):
        return value

    def sub(m):
        name = m.group(1)
        if name not in os.environ:
            raise ConfigError(f"environment variable {name} is not set (referenced as ${{{name}}})")
        return os.environ[name]

    return re.sub(r"\$\{(\w+)\}", sub, value)


def load(env):
    cfg = {}
    for name in ("base", env):
        cfg.update(_parse(f"config/{name}.json"))
    return {k: _expand(v) for k, v in cfg.items()}

