"""Configuration loading: config/base.ini overlaid by config/<env>.ini; ${VAR} references are resolved from the environment."""
import os
import re

import configparser


def _parse(path):
    cp = configparser.ConfigParser()
    cp.optionxform = str
    with open(path, encoding="utf-8") as fh:
        cp.read_file(fh)
    return {k: _coerce(v) for k, v in cp["settings"].items()}


def _coerce(text):
    low = text.strip().lower()
    if low in ("true", "false"):
        return low == "true"
    for conv in (int, float):
        try:
            return conv(text)
        except ValueError:
            pass
    return text.strip()


class ConfigError(Exception):
    """The configuration cannot be used."""


def _expand(value):
    if not isinstance(value, str):
        return value

    def sub(m):
        name = m.group(1)
        if name not in os.environ:
            raise ConfigError(f"environment variable {name} is not set (referenced as ${{{name}}})")
        return os.environ[name]

    return re.sub(r"\$\{(\w+)\}", sub, value)


def load(env):
    cfg = {}
    for name in ("base", env):
        cfg.update(_parse(f"config/{name}.ini"))
    return {k: _expand(v) for k, v in cfg.items()}

