"""Configuration loading: config/base.env overlaid by config/<env>.env; ${VAR} references are resolved from the environment."""
import os
import re

def _parse(path):
    out = {}
    with open(path, encoding="utf-8") as fh:
        for raw in fh:
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            key, _, value = line.partition("=")
            out[key.strip()] = _coerce(value.strip().strip('"'))
    return out


def _coerce(text):
    low = text.lower()
    if low in ("true", "false"):
        return low == "true"
    for conv in (int, float):
        try:
            return conv(text)
        except ValueError:
            pass
    return text


class ConfigError(Exception):
    """The configuration cannot be used."""


def _expand(value):
    if not isinstance(value, str):
        return value

    def sub(m):
        name = m.group(1)
        if name not in os.environ:
            raise ConfigError(f"environment variable {name} is not set (referenced as ${{{name}}})")
        return os.environ[name]

    return re.sub(r"\$\{(\w+)\}", sub, value)


def load(env):
    cfg = {}
    for name in ("base", env):
        cfg.update(_parse(f"config/{name}.env"))
    return {k: _expand(v) for k, v in cfg.items()}

